draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(0, H/2 + 50 + 20 * Math.sin(t));
  ctx.lineTo(W, H/2 + 50 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0, H/2 - 50 + 20 * Math.cos(t));
  ctx.lineTo(W, H/2 - 50 + 20 * Math.cos(t));
  ctx.stroke();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.restore();
}
